use Rendimiento_academico_UES;

-- Tabla: Rendimiento_academico
CREATE TABLE Rendimiento_academico (
    carnet VARCHAR(20) NOT NULL,
    ciclo VARCHAR(20) NOT NULL,
    materia VARCHAR(150) NOT NULL,
    nota_teoria NUMERIC(5,2),
